  //  https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6864719/
  proc_control_B.t14_j = ((b_this->xl[3] * b_this->xl[3] + b_this->xl[4] *
    b_this->xl[4]) + b_this->xl[5] * b_this->xl[5]) + b_this->xl[6] * b_this->
    xl[6];
  proc_control_B.qt[0] = b_this->xl[3] / proc_control_B.t14_j;
  proc_control_B.qt[1] = -b_this->xl[4] / proc_control_B.t14_j;
  proc_control_B.qt[2] = -b_this->xl[5] / proc_control_B.t14_j;
  proc_control_B.qt[3] = -b_this->xl[6] / proc_control_B.t14_j;
  proc_control_quatmultiply(&y[3], proc_control_B.qt, &Z[3]);

  //  Linéariser le systeme.
  //  Fonction qui linéarise le systeme
  // ------------------------------------------------------------------------------ 
