// Function for MATLAB Function: '<S147>/NLMPC'
void proc_control::proc_control_test_exit(sG8JZ69axY52WWR6RKyApQC_proc__T
  *MeritFunction, const s_PAtG1CW05sRYOWrqzwRQyC_proc_T *WorkingSet,
  s_WVbWSSvCeJzx5TXXa9L1l_proc__T *TrialState, const real_T lb[139], boolean_T
  *Flags_gradOK, boolean_T *Flags_fevalOK, boolean_T *Flags_done, boolean_T
  *Flags_stepAccepted, boolean_T *Flags_failedLineSearch, int32_T
  *Flags_stepType)
{
  int32_T idx_max;
  int32_T k;
  int32_T mLambda;
  int32_T nVar;
  boolean_T isFeasible;
  *Flags_fevalOK = true;
  *Flags_stepAccepted = false;
  *Flags_failedLineSearch = false;
  *Flags_stepType = 1;
  nVar = WorkingSet->nVar;
  mLambda = (((WorkingSet->sizes[0] + WorkingSet->sizes[2]) + WorkingSet->sizes
              [3]) + WorkingSet->sizes[4]) + 129;
  if (mLambda >= 0) {
    std::memcpy(&TrialState->lambdaStopTest.data[0], &TrialState->
                lambdasqp.data[0], static_cast<uint32_T>(mLambda + 1) * sizeof
                (real_T));
  }

  proc_control_computeGradLag(TrialState->gradLag.data, WorkingSet->ldA,
    WorkingSet->nVar, TrialState->grad.data, WorkingSet->sizes[2],
    WorkingSet->Aineq.data, WorkingSet->Aeq.data, WorkingSet->indexFixed.data,
    WorkingSet->sizes[0], WorkingSet->indexLB.data, WorkingSet->sizes[3],
    WorkingSet->indexUB.data, WorkingSet->sizes[4],
    TrialState->lambdaStopTest.data);
  if (WorkingSet->nVar < 1) {
    idx_max = 0;
  } else {
    idx_max = 1;
    if (WorkingSet->nVar > 1) {
      proc_control_B.smax_dq = std::abs(TrialState->grad.data[0]);
      for (k = 2; k <= nVar; k++) {
        proc_control_B.s_a3 = std::abs(TrialState->grad.data[k - 1]);
        if (proc_control_B.s_a3 > proc_control_B.smax_dq) {
          idx_max = k;
          proc_control_B.smax_dq = proc_control_B.s_a3;
        }
      }
    }
  }

  proc_control_B.smax_dq = std::fmax(1.0, std::abs(TrialState->grad.data[idx_max
    - 1]));
  if (std::isinf(proc_control_B.smax_dq)) {
    proc_control_B.smax_dq = 1.0;
  }

  MeritFunction->nlpPrimalFeasError = proc_con_computePrimalFeasError
    (TrialState->xstarsqp, WorkingSet->sizes[2] - TrialState->mNonlinIneq,
     TrialState->mNonlinIneq, TrialState->cIneq.data, TrialState->cEq,
     WorkingSet->indexLB.data, WorkingSet->sizes[3], lb,
     WorkingSet->indexUB.data, WorkingSet->sizes[4]);
  MeritFunction->feasRelativeFactor = std::fmax(1.0,
    MeritFunction->nlpPrimalFeasError);
  isFeasible = (MeritFunction->nlpPrimalFeasError <= 0.02 *
                MeritFunction->feasRelativeFactor);
  proc_contr_computeDualFeasError(WorkingSet->nVar, TrialState->gradLag.data,
    Flags_gradOK, &MeritFunction->nlpDualFeasError);
  if (!*Flags_gradOK) {
    *Flags_done = true;
    if (isFeasible) {
      TrialState->sqpExitFlag = 2;
    } else {
      TrialState->sqpExitFlag = -2;
    }
  } else {
    MeritFunction->nlpComplError = 0.0;
    MeritFunction->firstOrderOpt = std::fmax(MeritFunction->nlpDualFeasError,
      0.0);
    if (mLambda >= 0) {
      std::memcpy(&TrialState->lambdaStopTestPrev.data[0],
                  &TrialState->lambdaStopTest.data[0], static_cast<uint32_T>
                  (mLambda + 1) * sizeof(real_T));
    }

    if (isFeasible && (MeritFunction->nlpDualFeasError <= 0.02 *
                       proc_control_B.smax_dq)) {
      *Flags_done = true;
      TrialState->sqpExitFlag = 1;
    } else {
      *Flags_done = false;
      if (isFeasible && (TrialState->sqpFval < -1.0E+20)) {
        *Flags_done = true;
        TrialState->sqpExitFlag = -3;
      }
    }
  }
}

